import json, subprocess, sys
WIKI = "List the wiki with `hercule wiki-page list --resource 01a11895-1bb8-70f5-b877-330bc92fdd49` and read a page with `hercule wiki-page read <id>`."
runs = [
 ("7e523471", "client-core",
  "packages/client-core/src: the client library every app uses. The live connection (live/), the thread and transcript logic (threads/), and the functions that interpret domain data for the screens (intake, tracking, your-work, waiting, run-*, workflow-*). Look hardest at how live pushes and reads combine. The wiki pages derived-shell-reads-and-query-races, done-trip-review-lessons and try-again-lock-in-mutation-cache describe the races found so far. " + WIKI),
 ("7e523471", "desktop screens",
  "apps/desktop/src/renderer/screens and apps/desktop/src/renderer/routes: the desktop app's screens (threads with their transcript and composer, Intake, runs, workflows, settings, wiki, discussions). Look hardest at state that a live push or a route change can leave stale, focus and selection after a list changes, optimistic updates, and Undo. Do not hunt in office/ or specimens/. The wiki pages tracking-pane-lessons, desktop-thread-copies, route-pending-component-in-tests and sidebar-groups-and-mac-checks describe the traps found so far. " + WIKI),
 ("7e523471", "controller sessions",
  "apps/controller/src/sessions, apps/controller/src/daemon/sessions and apps/controller/src/live: sessions, their inputs, questions and approvals, resume and fork, reconciliation with runner reports, and the live topics clients subscribe to. Spec 06 and spec 03 are normative. Look hardest at status moves that race with runner frames, queued inputs on a session that exits, and pushes sent before a transaction commits."),
 ("7e523471", "runner",
  "apps/runner/src: the runner daemon, the provider adapters (providers/: Claude Code, Codex, pi), session supervision and timeouts, workspaces and workspace steps, skills and credentials. Specs 03 and 06 are normative. Look hardest at the normalized event stream (ordering, partial lines, subagents, questions that disappear; wiki page provider-user-question-failures), idle unload and resume, reconnects to the controller, and git operations in worktrees. " + WIKI),
 ("4890db19", "client-core and desktop renderer",
  "packages/client-core/src and apps/desktop/src/renderer: what the desktop app does per live push and per streamed token, how long threads with thousands of transcript events take to open and scroll, markdown and diff rendering of big inputs, and reads repeated on every push. Earlier fixes in this area are PRs #778, #783, #785, #815 and #816. The wiki pages desktop-render-perf-measuring, thread-open-latency-repro and live-stream-replay-and-hidden-pages describe how to measure on Linux. The desktop first screen bundle is 448-455 kB gzipped against a 250 kB guide (scripts/check-bundle-budget.ts); a real cut there counts as a problem too. " + WIKI),
 ("7e523471", "controller runs and workflows",
  "apps/controller/src/runs, apps/controller/src/workflows, apps/controller/src/expressions, apps/controller/src/daemon/runs and apps/controller/src/daemon/workflows: the run engine (joins, skips, cycles, terminal steps, signal triggers), workflow validation, CEL templates, and the Scheduler for cron triggers. Spec 07 is normative. Look hardest at the settled rule for join: all, edge counts and maxTraversals, a cancel during a step, a controller restart mid-run, and cron times around daylight saving time (the clocks go back on 2026-10-25 in Europe/Amsterdam). Known flake, not yours: scheduler.integration.test.ts fails around 02:00 UTC because it reads the wall clock; fix it only if you can prove the bug is in the Scheduler and not in the test."),
 ("7e523471", "controller events, signals and notifications",
  "apps/controller/src/events, signals, subscriptions, notifications, tasks, intake-settings and bound-actions, plus apps/controller/src/daemon/events, daemon/ingest and daemon/bound-actions: the event pipeline and router, enrichment, Intake signals and screening, subscriptions, notifications and their bound actions, and tasks. Specs 08, 09 and 10 are normative. Look hardest at idempotency (an event routed twice, enrichment re-matching one event), spawn bounds and breakers, and handing a signal off."),
 ("7e523471", "desktop shell and main process",
  "apps/desktop/src/renderer/app, apps/desktop/src/renderer/shell, apps/desktop/src/main, apps/desktop/src/preload and apps/desktop/src/ipc: the renderer's wiring (router, queries, live connection), the shell (sidebar, header, windows), the Electron main process and the typed bridge. Spec 17 is normative. Look hardest at the shell reads that must stay cached for the life of the window (AGENTS.md, web app layout, point 8), reconnect and sign-in flows, the window lifecycle, and IPC messages that can arrive out of order."),
 ("4890db19", "controller queries and pushes",
  "apps/controller/src, every domain plus db/ and http/: SQL that scans or loads more than it needs, queries run once per row, missing indexes on hot reads (session lists, run lists, the event log, Intake, tracking), work done for every live push, and payloads larger than the client uses. Measure against a database filled to realistic sizes: thousands of sessions and runs, and hundreds of thousands of events."),
 ("4890db19", "runner streaming and workspaces",
  "apps/runner/src and packages/protocol/src: the work done per streamed token on the way from the provider adapters to the controller, transcript and diff handling for big sessions, frame sizes, memory held per session, and workspace provisioning and git work in worktrees."),
]
for wf, area, scope in runs:
    out = subprocess.run(["hercule","run","start","--workflow",wf,"--inputs",json.dumps({"area":area,"scope":scope})],capture_output=True,text=True)
    print(wf, area, "->", (out.stdout+out.stderr).strip()[:200])
